783	/// An error reported by the tokenizer, with a human-readable `message` and a `location`.
784	#[derive(Debug, PartialEq, Eq)]
785	pub struct TokenizerError {
786	    /// A descriptive error message.
787	    pub message: String,
788	    /// The `Location` where the error was detected.
789	    pub location: Location,
790	}
