800	struct State<'a> {
801	    peekable: Peekable<Chars<'a>>,
802	    line: u64,
803	    col: u64,
804	}
805	
806	impl State<'_> {
807	    /// return the next character and advance the stream
808	    pub fn next(&mut self) -> Option<char> {
809	        match self.peekable.next() {
810	            None => None,
811	            Some(s) => {
812	                if s == '\n' {
813	                    self.line += 1;
814	                    self.col = 1;
815	                } else {
816	                    self.col += 1;
817	                }
818	                Some(s)
819	            }
820	        }
821	    }
822	
823	    /// return the next character but do not advance the stream
824	    pub fn peek(&mut self) -> Option<&char> {
825	        self.peekable.peek()
826	    }
827	
828	    /// Return the current `Location` (line and column)
829	    pub fn location(&self) -> Location {
830	        Location {
831	            line: self.line,
832	            column: self.col,
833	        }
834	    }
835	}
