837	/// Represents how many quote characters enclose a string literal.
838	#[derive(Copy, Clone)]
839	enum NumStringQuoteChars {
840	    /// e.g. `"abc"`, `'abc'`, `r'abc'`
841	    One,
842	    /// e.g. `"""abc"""`, `'''abc'''`, `r'''abc'''`
843	    Many(NonZeroU8),
844	}
845	
846	/// Settings for tokenizing a quoted string literal.
847	struct TokenizeQuotedStringSettings {
848	    /// The character used to quote the string.
849	    quote_style: char,
850	    /// Represents how many quotes characters enclose the string literal.
851	    num_quote_chars: NumStringQuoteChars,
852	    /// The number of opening quotes left to consume, before parsing
853	    /// the remaining string literal.
854	    /// For example: given initial string `"""abc"""`. If the caller has
855	    /// already parsed the first quote for some reason, then this value
856	    /// is set to 1, flagging to look to consume only 2 leading quotes.
857	    num_opening_quotes_to_consume: u8,
858	    /// True if the string uses backslash escaping of special characters
859	    /// e.g `'abc\ndef\'ghi'
860	    backslash_escape: bool,
861	}
