863	/// SQL Tokenizer
864	pub struct Tokenizer<'a> {
865	    dialect: &'a dyn Dialect,
866	    query: &'a str,
867	    /// If true (the default), the tokenizer will un-escape literal
868	    /// SQL strings See [`Tokenizer::with_unescape`] for more details.
869	    unescape: bool,
870	}
871	
872	impl<'a> Tokenizer<'a> {
873	    /// Create a new SQL tokenizer for the specified SQL statement
874	    ///
875	    /// ```
876	    /// # use sqlparser::tokenizer::{Token, Whitespace, Tokenizer};
877	    /// # use sqlparser::dialect::GenericDialect;
878	    /// # let dialect = GenericDialect{};
879	    /// let query = r#"SELECT 'foo'"#;
880	    ///
881	    /// // Parsing the query
882	    /// let tokens = Tokenizer::new(&dialect, &query).tokenize().unwrap();
883	    ///
884	    /// assert_eq!(tokens, vec![
885	    ///   Token::make_word("SELECT", None),
886	    ///   Token::Whitespace(Whitespace::Space),
887	    ///   Token::SingleQuotedString("foo".to_string()),
888	    /// ]);
889	    pub fn new(dialect: &'a dyn Dialect, query: &'a str) -> Self {
890	        Self {
891	            dialect,
892	            query,
893	            unescape: true,
894	        }
895	    }
896	
897	    /// Set unescape mode
898	    ///
899	    /// When true (default) the tokenizer unescapes literal values
900	    /// (for example, `""` in SQL is unescaped to the literal `"`).
901	    ///
902	    /// When false, the tokenizer provides the raw strings as provided
903	    /// in the query.  This can be helpful for programs that wish to
904	    /// recover the *exact* original query text without normalizing
905	    /// the escaping
906	    ///
907	    /// # Example
908	    ///
909	    /// ```
910	    /// # use sqlparser::tokenizer::{Token, Tokenizer};
911	    /// # use sqlparser::dialect::GenericDialect;
912	    /// # let dialect = GenericDialect{};
913	    /// let query = r#""Foo "" Bar""#;
914	    /// let unescaped = Token::make_word(r#"Foo " Bar"#, Some('"'));
915	    /// let original  = Token::make_word(r#"Foo "" Bar"#, Some('"'));
916	    ///
917	    /// // Parsing with unescaping (default)
918	    /// let tokens = Tokenizer::new(&dialect, &query).tokenize().unwrap();
919	    /// assert_eq!(tokens, vec![unescaped]);
920	    ///
921	    /// // Parsing with unescape = false
922	    /// let tokens = Tokenizer::new(&dialect, &query)
923	    ///    .with_unescape(false)
924	    ///    .tokenize().unwrap();
925	    /// assert_eq!(tokens, vec![original]);
926	    /// ```
927	    pub fn with_unescape(mut self, unescape: bool) -> Self {
928	        self.unescape = unescape;
929	        self
930	    }
931	
932	    /// Tokenize the statement and produce a vector of tokens
933	    pub fn tokenize(&mut self) -> Result<Vec<Token>, TokenizerError> {
934	        let twl = self.tokenize_with_location()?;
935	        Ok(twl.into_iter().map(|t| t.token).collect())
936	    }
937	
938	    /// Tokenize the statement and produce a vector of tokens with location information
939	    pub fn tokenize_with_location(&mut self) -> Result<Vec<TokenWithSpan>, TokenizerError> {
940	        let mut tokens: Vec<TokenWithSpan> = vec![];
941	        self.tokenize_with_location_into_buf(&mut tokens)
942	            .map(|_| tokens)
943	    }
944	
945	    /// Tokenize the statement and append tokens with location information into the provided buffer.
946	    /// If an error is thrown, the buffer will contain all tokens that were successfully parsed before the error.
947	    pub fn tokenize_with_location_into_buf(
948	        &mut self,
949	        buf: &mut Vec<TokenWithSpan>,
950	    ) -> Result<(), TokenizerError> {
951	        self.tokenize_with_location_into_buf_with_mapper(buf, |token| token)
952	    }
953	
954	    /// Tokenize the statement and produce a vector of tokens, mapping each token
955	    /// with provided `mapper`
956	    pub fn tokenize_with_location_into_buf_with_mapper(
957	        &mut self,
958	        buf: &mut Vec<TokenWithSpan>,
959	        mut mapper: impl FnMut(TokenWithSpan) -> TokenWithSpan,
960	    ) -> Result<(), TokenizerError> {
961	        let mut state = State {
962	            peekable: self.query.chars().peekable(),
963	            line: 1,
964	            col: 1,
965	        };
966	
967	        let mut location = state.location();
968	        while let Some(token) = self.next_token(&mut state, buf.last().map(|t| &t.token))? {
969	            let span = location.span_to(state.location());
970	
971	            // Check if this is a multiline comment hint that should be expanded
972	            match &token {
973	                Token::Whitespace(Whitespace::MultiLineComment(comment))
974	                    if self.dialect.supports_multiline_comment_hints()
975	                        && comment.starts_with('!') =>
976	                {
977	                    // Re-tokenize the hints and add them to the buffer
978	                    self.tokenize_comment_hints(comment, span, buf, &mut mapper)?;
979	                }
980	                _ => {
981	                    buf.push(mapper(TokenWithSpan { token, span }));
982	                }
983	            }
984	
985	            location = state.location();
986	        }
987	        Ok(())
988	    }
989	
990	    /// Re-tokenize optimizer hints from a multiline comment and add them to the buffer.
991	    /// For example, `/*!50110 KEY_BLOCK_SIZE = 1024*/` becomes tokens for `KEY_BLOCK_SIZE = 1024`
992	    fn tokenize_comment_hints(
993	        &self,
994	        comment: &str,
995	        span: Span,
996	        buf: &mut Vec<TokenWithSpan>,
997	        mut mapper: impl FnMut(TokenWithSpan) -> TokenWithSpan,
998	    ) -> Result<(), TokenizerError> {
999	        // Strip the leading '!' and any version digits (e.g., "50110")
1000	        let hint_content = comment
1001	            .strip_prefix('!')
1002	            .unwrap_or(comment)
1003	            .trim_start_matches(|c: char| c.is_ascii_digit());
1004	
1005	        // If there's no content after stripping, nothing to tokenize
1006	        if hint_content.is_empty() {
1007	            return Ok(());
1008	        }
1009	
1010	        // Create a new tokenizer for the hint content
1011	        let inner = Tokenizer::new(self.dialect, hint_content).with_unescape(self.unescape);
1012	
1013	        // Create a state for tracking position within the hint
1014	        let mut state = State {
1015	            peekable: hint_content.chars().peekable(),
1016	            line: span.start.line,
1017	            col: span.start.column,
1018	        };
1019	
1020	        // Tokenize the hint content and add tokens to the buffer
1021	        let mut location = state.location();
1022	        while let Some(token) = inner.next_token(&mut state, buf.last().map(|t| &t.token))? {
1023	            let token_span = location.span_to(state.location());
1024	            buf.push(mapper(TokenWithSpan {
1025	                token,
1026	                span: token_span,
1027	            }));
1028	            location = state.location();
1029	        }
1030	
1031	        Ok(())
1032	    }
1033	
1034	    // Tokenize the identifier or keywords in `ch`
1035	    fn tokenize_identifier_or_keyword(
1036	        &self,
1037	        ch: impl IntoIterator<Item = char>,
1038	        chars: &mut State,
1039	    ) -> Result<Option<Token>, TokenizerError> {
1040	        chars.next(); // consume the first char
1041	        let ch: String = ch.into_iter().collect();
1042	        let word = self.tokenize_word(ch, chars);
1043	
1044	        // TODO: implement parsing of exponent here
1045	        if word.chars().all(|x| x.is_ascii_digit() || x == '.') {
1046	            let mut inner_state = State {
1047	                peekable: word.chars().peekable(),
1048	                line: 0,
