2298	    /// Skips whitespace, single-line comments (`-- ...`) and multi-line
2299	    /// comments (`/* ... */`) in `chars`.
2300	    fn skip_whitespace_and_comments(&self, chars: &mut State) -> Result<(), TokenizerError> {
2301	        loop {
2302	            let mut lookahead = chars.peekable.clone();
2303	            match lookahead.next() {
2304	                Some(c) if c.is_whitespace() => {
2305	                    chars.next();
2306	                }
2307	                Some('-') if matches!(lookahead.next(), Some('-')) => {
2308	                    chars.next(); // consume the first '-'
2309	                    chars.next(); // consume the second '-'
2310	                    while let Some(c) = chars.next() {
2311	                        if c == '\n' {
2312	                            break;
2313	                        }
2314	                    }
2315	                }
2316	                Some('/') if matches!(lookahead.next(), Some('*')) => {
2317	                    chars.next(); // consume the '/'
2318	                    chars.next(); // consume the '*'
2319	                    self.skip_multi_line_comment(chars)?;
2320	                }
2321	                _ => return Ok(()),
2322	            }
2323	        }
2324	    }
