2326	    /// Skips a multi-line comment body (after the opening `/*`), honoring
2327	    /// nested comments if the dialect supports them.
2328	    fn skip_multi_line_comment(&self, chars: &mut State) -> Result<(), TokenizerError> {
2329	        let mut nested = 1;
2330	        let supports_nested_comments = self.dialect.supports_nested_comments();
2331	        loop {
2332	            match chars.next() {
2333	                Some('/') if matches!(chars.peek(), Some('*')) && supports_nested_comments => {
2334	                    chars.next(); // consume the '*'
2335	                    nested += 1;
2336	                }
2337	                Some('*') if matches!(chars.peek(), Some('/')) => {
2338	                    chars.next(); // consume the '/'
2339	                    nested -= 1;
2340	                    if nested == 0 {
2341	                        return Ok(());
2342	                    }
2343	                }
2344	                Some(_) => {}
